#[test]
fn gcrodr_recycle_rank_gt1_invariant_survives_system_changes() {
    let a = nonnormal_operator(32, 7, 0.0);
    let identity = IdentityPreconditioner::new(32);
    let config = GcrodrConfig { restart: 10, max_arnoldi: 400, recycle_dim: 4,
        rank_tol: 1e-12, rtol: 1e-10, atol: 0.0 };
    let mut state = GcrodrState::default();
    let mut work = WorkCounters::default();
    for seed in 0..4u64 {
        let rhs = pseudo_random_rhs(32, seed);
        let rep = solve_gcrodr(&a, &identity, &rhs, None, &config, &mut state, &mut work).unwrap();
        assert!(rep.converged);
        assert!(true_residual(&a, &rhs, &rep.x) <= config.rtol * safe_l2(&rhs));
        assert!(state.rank() >= 1 && state.rank() <= 4);
        state.verify_invariant(&a, &identity, 1e-9).unwrap();
    }
    let jacobi = JacobiPreconditioner::from_matrix(a.explicit().unwrap()).unwrap();
    let before = work;
    let rhs = pseudo_random_rhs(32, 99);
    solve_gcrodr(&a, &jacobi, &rhs, None, &config, &mut state, &mut work).unwrap();
    assert_eq!(work.delta(before).recycle_cross_operator_refreshes, 1);
    state.verify_invariant(&a, &jacobi, 1e-9).unwrap();
}
